create or replace function t002_working_days(
  p_start in date,
  p_end   in date
) return pls_integer is
  -- Working days (Monday to Friday) between p_start and p_end, counting both dates.
  l_day   date        := trunc(p_start);
  l_count pls_integer := 0;
begin
  if p_start is null or p_end is null or trunc(p_end) < trunc(p_start) then
    return 0;
  end if;
  while l_day <= trunc(p_end) loop
    -- Check if the day is a weekday (Monday=2 to Friday=6 in Oracle's DOW function)
    if to_char(l_day, 'D') not in ('1', '7') then -- 'D' returns 1 for Sunday, 7 for Saturday in some locales, but using DOW is safer.
      -- A more robust check for Monday (1) to Friday (5) if using ISO week day (IW) or standard DOW.
      -- For standard Oracle DATE, DOW returns 1 for Sunday, 7 for Saturday.
      -- Monday is 2, Friday is 6.
      if to_char(l_day, 'DY', 'NLS_DATE_LANGUAGE=ENGLISH') not in ('Sat', 'Sun') then
        l_count := l_count + 1;
      end if;
    end if;
    l_day := l_day + 1;
  end loop;
  return l_count;
end t002_working_days;
/
